<?php
$title='Shortcodes Maker';require __DIR__.'/inc/header.php';$pdo=db();$message='';
if(is_post()){verify_csrf();$a=(string)post('action','');if($a==='save'){$id=(int)post('id',0);$label=trim((string)post('label'));$code=slugify((string)post('code'));$code='['.$code.']';$type=(string)post('content_type','text');$content=(string)post('content');if($id)$pdo->prepare('UPDATE shortcodes SET label=?,code=?,content_type=?,content=?,status=? WHERE id=?')->execute([$label,$code,$type,$content,post('status')?1:0,$id]);else $pdo->prepare('INSERT INTO shortcodes(label,code,content_type,content,status) VALUES(?,?,?,?,?)')->execute([$label,$code,$type,$content,1]);flash('success',$id?'Shortcode updated.':'Shortcode created.');redirect('/admin/shortcodes.php');}if($a==='delete'){$pdo->prepare('DELETE FROM shortcodes WHERE id=?')->execute([(int)post('id')]);flash('success','Shortcode deleted.');redirect('/admin/shortcodes.php');}if($a==='toggle'){$pdo->prepare('UPDATE shortcodes SET status=1-status WHERE id=?')->execute([(int)post('id')]);flash('success','Shortcode status changed.');redirect('/admin/shortcodes.php');}}
$editId=(int)get('edit',0);$edit=null;if($editId){$st=$pdo->prepare('SELECT * FROM shortcodes WHERE id=?');$st->execute([$editId]);$edit=$st->fetch();}$form=$edit?:['id'=>0,'label'=>'','code'=>'','content_type'=>'html','content'=>'','status'=>1];$rows=$pdo->query('SELECT * FROM shortcodes ORDER BY id DESC')->fetchAll();
?>
