nded-2xl border p-4"><div class="flex-1 min-w-0"><div class="font-bold"><?=e($r['label'])?></div><code class="text-xs bg-slate-100 px-2 py-1 rounded-lg"><?=e($r['code'])?></code><div class="text-sm text-slate-500 mt-2 line-clamp-3"><?=e(strip_tags($r['content']))?></div></div><div class="flex flex-col gap-2"><a href="?edit=<?=$r['id']?>" class="px-3 py-2 rounded-xl bg-blue-50 text-blue-700 text-xs font-bold">Edit</a><button onclick="navigator.clipboard.writeText('<?=e($r['code'])?>')" class="px-3 py-2 rounded-xl bg-slate-950 text-white text-xs font-bold">Copy</button><form method="post"><?=csrf_input()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="px-3 py-2 rounded-xl bg-slate-100 text-xs font-bold"><?=$r['status']?'Disable':'Enable'?></button></form><form method="post" onsubmit="return confirm('Delete shortcode?')"><?=csrf_input()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="px-3 py-2 rounded-xl bg-rose-50 text-rose-700 text-xs font-bold">Delete</button></form></div></div><?php endforeach;?></div></div></div>
